changeEventDetails.code:
type OTPFieldRootChangeEventDetails = ({
    reason: 'input-change';
    event: InputEvent | Event;
} | {
    reason: 'input-clear';
    event: InputEvent | Event | FocusEvent;
} | {
    reason: 'input-paste';
    event: ClipboardEvent;
} | {
    reason: 'keyboard';
    event: KeyboardEvent;
}) & {
    cancel: () => void;
    allowPropagation: () => void;
    isCanceled: boolean;
    isPropagationAllowed: boolean;
    trigger: Element | undefined;
};

